```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# TOP LEVEL
#################################################################

ea:EducationalAssessment a owl:Class ;
  rdfs:label "Educational Assessment" ;
  skos:altLabel "educational evaluation", "assessment" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Examination a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:label "Examination" ;
  skos:altLabel "test", "exam" ;
  rdfs:comment "Assessment is often used interchangeably with 'test' but is not limited to tests; Examination/Test is modeled as a subclass of EducationalAssessment." .

#################################################################
# GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  owl:disjointUnionOf ( ea:IndividualLearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:ProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:IndividualLearnerGranularity a owl:Class .
ea:LearningCommunityGranularity a owl:Class .
ea:CourseGranularity a owl:Class .
ea:ProgramGranularity a owl:Class .
ea:InstitutionGranularity a owl:Class .
ea:EducationalSystemGranularity a owl:Class .

#################################################################
# PURPOSE / TIMING AXIS  (Placement, Formative, Summative, Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class .
ea:FormativePurpose a owl:Class .
ea:SummativePurpose a owl:Class .
ea:DiagnosticPurpose a owl:Class .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "placement evaluation", "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "formative evaluation", "educative assessment", "assessment for learning", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic Assessment" ;
  skos:altLabel "diagnostic testing" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists Placement, Formative, Summative and Diagnostic as four coordinate, mutually exclusive categories of assessment (hence disjoint via PurposeCategory). Another passage states 'A common form of formative assessment is diagnostic assessment', which subordinates DiagnosticAssessment under FormativeAssessment. Both claims are encoded; the subClassOf axiom together with the disjointness of DiagnosticPurpose/FormativePurpose renders DiagnosticAssessment potentially empty, which is accepted as a faithful record of the conflicting source claims." .

#################################################################
# ASSESSOR ROLE & SELF-ASSESSMENT
#################################################################

ea:hasAssessor a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AssessorRole .

ea:AssessorRole a owl:Class ;
  owl:disjointUnionOf ( ea:TeacherAssessorRole ea:PeerAssessorRole ea:LearnerAssessorRole ) .

ea:TeacherAssessorRole a owl:Class .
ea:PeerAssessorRole a owl:Class .
ea:LearnerAssessorRole a owl:Class .

ea:SelfAssessment a owl:Class ;
  rdfs:label "Self Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:DiagnosticAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasAssessor ; owl:someValuesFrom ea:LearnerAssessorRole ] ) ] ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

#################################################################
# TEMPORAL ORIENTATION AXIS (shared by ForwardLookingAssessment, AchievementTest, AptitudeTest)
#################################################################

ea:hasTemporalOrientation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:TemporalOrientationCategory .

ea:TemporalOrientationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:BackwardLookingOrientation ea:ForwardLookingOrientation ) .

ea:BackwardLookingOrientation a owl:Class .
ea:ForwardLookingOrientation a owl:Class .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:label "Forward-Looking Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceFormatCategory a owl:Class ;
  owl:disjointUnionOf ( ea:Product ea:Performance ) .

ea:Product a owl:Class ; rdfs:comment "e.g. a painting, portfolio, paper, or exhibition." .
ea:Performance a owl:Class ; rdfs:comment "e.g. a speech, athletic skill, musical recital, or reading." .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:label "Performance-Based Assessment" ;
  rdfs:comment "Similar to summative assessment; focuses on achievement via a well-defined task producing a Product or a Performance. Performance formats are classified into products and performances (coordinate, disjoint)." .

ea:hasContext a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ContextCategory .

ea:ContextCategory a owl:Class ;
  owl:disjointUnionOf ( ea:RealisticContext ea:SchoolContext ) .

ea:RealisticContext a owl:Class .
ea:SchoolContext a owl:Class .

ea:AuthenticAssessment a owl:Class ;
  rdfs:label "Authentic Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting. NOTE: the corpus also states that performance assessments 'may also be called authentic assessments', suggesting partial synonymy with PerformanceBasedAssessment even though each is given a distinct differentia here." .

#################################################################
# OBJECTIVE / SUBJECTIVE AXIS (assessments and items)
#################################################################

ea:hasResponseStructure a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain [ owl:unionOf ( ea:EducationalAssessment ea:TestItem ) ] ;
  rdfs:range ea:ResponseStructureCategory .

ea:ResponseStructureCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ObjectiveResponseStructure ea:SubjectiveResponseStructure ) .

ea:ObjectiveResponseStructure a owl:Class .
ea:SubjectiveResponseStructure a owl:Class .

ea:ObjectiveAssessment a owl:Class ;
  rdfs:label "Objective Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseStructure ; owl:someValuesFrom ea:ObjectiveResponseStructure ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
  rdfs:label "Subjective Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseStructure ; owl:someValuesFrom ea:SubjectiveResponseStructure ] ) ] ;
  rdfs:comment "Some argue the objective/subjective distinction is neither useful nor accurate since all assessment involves inherent bias." .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ;
  rdfs:label "Test Item" ;
  rdfs:comment "Colloquially called 'questions' though many items are not phrased as questions." .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasResponseStructure ; owl:someValuesFrom ea:ObjectiveResponseStructure ] ) ] .

ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasResponseStructure ; owl:someValuesFrom ea:SubjectiveResponseStructure ] ) ] .

ea:hasStem a owl:DatatypeProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range xsd:string .

ea:AnswerOption a owl:Class ;
  rdfs:label "Answer Option" .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "The correct answer option(s) for an item." .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "Incorrect but plausible answer options." .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:label "Multiple Choice Item" ;
  skos:altLabel "MCQ", "objective response item" ;
  rdfs:subClassOf ea:ObjectiveItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:qualifiedCardinality 1 ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "Only one answer may be keyed as correct; there are two families of multiple-choice items: True/False and One-Best-Answer." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:label "Multiple Response Item" ;
  rdfs:subClassOf ea:ObjectiveItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minQualifiedCardinality 2 ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, in contrast to MultipleChoiceItem." .

ea:OneBestAnswerItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires a test taker to choose only one answer from a list." .

ea:TrueFalseFamilyItem a owl:Class ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires choosing all appropriate answers; one of the two families of multiple-choice questions." .

ea:TrueFalseItem a owl:Class ;
  rdfs:label "True/False Item" ;
  rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists true/false as a coordinate objective item type alongside multiple-choice, multiple-response and matching questions; another passage treats True/False as one of the 'two families' (i.e. a subtype) of multiple-choice items. Both the coordinate placement under ObjectiveItem and the subordinate placement under MultipleChoiceItem are encoded." .

ea:MatchingItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem .

ea:FillInTheBlankItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem .

ea:hasWordBankProvision a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:FillInTheBlankItem ;
  rdfs:range ea:WordBankProvisionCategory .

ea:WordBankProvisionCategory a owl:Class ;
  owl:disjointUnionOf ( ea:WordBankProvided ea:NoWordBankProvided ) .

ea:WordBankProvided a owl:Class .
ea:NoWordBankProvided a owl:Class .

ea:WordBankFillInTheBlankItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:FillInTheBlankItem
    [ a owl:Restriction ; owl:onProperty ea:hasWordBankProvision ; owl:someValuesFrom ea:WordBankProvided ] ) ] .

ea:OpenFillInTheBlankItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:FillInTheBlankItem
    [ a owl:Restriction ; owl:onProperty ea:hasWordBankProvision ; owl:someValuesFrom ea:NoWordBankProvided ] ) ] .

ea:ShortAnswerItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem .

ea:EssayItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "extended-response question", "free response question", "FRQ" .

ea:ItemBank a owl:Class ;
  rdfs:label "Item Bank" ;
  rdfs:comment "Items are stored in an item bank." .

ea:isItemOf a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range [ owl:unionOf ( ea:Examination ea:ItemBank ) ] .

ea:hasItem a owl:ObjectProperty ;
  owl:inverseOf ea:isItemOf ;
  rdfs:domain [ owl:unionOf ( ea:Examination ea:ItemBank ) ] ;
  rdfs:range ea:TestItem .

#################################################################
# REFERENCING AXIS (Criterion / Norm / Ipsative)
#################################################################

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ReferenceCategory .

ea:ReferenceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) .

ea:CriterionReference a owl:Class .
ea:NormReference a owl:Class .
ea:IpsativeReference a owl:Class .

ea:CriterionReferencedAssessment a owl:Class ;
  rdfs:label "Criterion-Referenced Assessment" ;
  skos:altLabel "criterion-referenced test", "CRT", "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria, e.g. a driving test." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedAssessment ;
  rdfs:range xsd:decimal .

ea:MasteryTest a owl:Class ;
  rdfs:subClassOf ea:CriterionReferencedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test with a cutscore where the examinee passes if the score exceeds the cutscore." .

ea:NormReferencedAssessment a owl:Class ;
  rdfs:label "Norm-Referenced Assessment" ;
  skos:altLabel "norm-referenced test", "NRT", "normative assessment", "grading on a curve" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] ;
  rdfs:comment "Relative to the student body; e.g. the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  rdfs:label "Ipsative Assessment" ;
  skos:altLabel "ipsative test", "forced-choice assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
  rdfs:comment "Self-comparison either over time or across domains within the same student." .

#################################################################
# FORMAL / INFORMAL AXIS
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalCategory a owl:Class .
ea:InformalCategory a owl:Class .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document and is given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Does not contribute to a student's final grade; includes observation, inventories, checklists, rating scales." .

#################################################################
# INTERNAL / EXTERNAL AXIS
#################################################################

ea:hasAdministeringLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalLocus a owl:Class .
ea:ExternalLocus a owl:Class .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministeringLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministeringLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# STANDARDIZATION AXIS
#################################################################

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Examination ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedCategory a owl:Class .
ea:NonStandardizedCategory a owl:Class .

ea:StandardizedTest a owl:Class ;
  rdfs:label "Standardized Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent, standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  rdfs:label "Non-Standardized Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

ea:AchievementTest a owl:Class ;
  rdfs:subClassOf ea:StandardizedTest ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:BackwardLookingOrientation ] ) ] ;
  rdfs:comment "Backward-looking: measures knowledge/skills already learned." .

ea:AptitudeTest a owl:Class ;
  rdfs:subClassOf ea:StandardizedTest ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] ;
  rdfs:comment "Forward-looking: attempts to predict future ability to succeed." .

ea:CollegeAdmissionsTest a owl:Class ;
  rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Used to decide which students are admitted to a collegiate program." .

ea:InternationalComparisonTest a owl:Class ;
  rdfs:subClassOf ea:StandardizedTest ;
  skos:altLabel "international benchmark test" ;
  rdfs:comment "e.g. PISA, PIRLS, TIMSS." .

ea:PsychologicalTest a owl:Class ;
  rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Used to measure cognitive abilities and mental, emotional, developmental and social characteristics, e.g. MMPI, IQ tests." .

#################################################################
# STAKES AXIS
#################################################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Examination ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesCategory a owl:Class .
ea:LowStakesCategory a owl:Class .

ea:HighStakesTest a owl:Class ;
  rdfs:label "High-Stakes Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward or punishment for performance, used for accountability." .

ea:LowStakesTest a owl:Class ;
  rdfs:label "Low-Stakes Test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CompetitiveExamination a owl:Class ;
  rdfs:label "Competitive Examination" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ]
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected; demonstrates that the purpose/reference/stakes/standardization axes are orthogonal, since 'a single test can have multiple qualities' (e.g. the bar exam is norm-referenced, standardized, and summative simultaneously)." .

#################################################################
# ADMINISTRATION MEDIUM AXIS
#################################################################

ea:hasAdministrationMedium a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Examination ;
  rdfs:range ea:AdministrationMediumCategory .

ea:AdministrationMediumCategory a owl:Class ;
  owl:disjointUnionOf ( ea:WrittenMedium ea:OnScreenMedium ea:PracticalMedium ) .

ea:WrittenMedium a owl:Class .
ea:OnScreenMedium a owl:Class .
ea:PracticalMedium a owl:Class .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMedium ; owl:someValuesFrom ea:WrittenMedium ] ) ] .

ea:OnScreenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMedium ; owl:someValuesFrom ea:OnScreenMedium ] ) ] .

ea:PerformanceTest a owl:Class ;
  rdfs:label "Performance Test" ;
  skos:altLabel "practical test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMedium ; owl:someValuesFrom ea:PracticalMedium ] ) ] ;
  rdfs:comment "Requires an examinee to actually perform a task or activity, e.g. a behind-the-wheel driving test." .

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Examination ;
  rdfs:comment "A brief assessment covering a small amount of material, usually formative and low-stakes." .

ea:MidtermExam a owl:Class ;
  rdfs:subClassOf ea:Examination ;
  rdfs:subClassOf [ owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "An exam given near the middle of an academic term; stated to be 'a type of formative or summative assessment' (i.e., a subclass of the union of the two, not necessarily both)." .

ea:FinalExam a owl:Class ;
  rdfs:subClassOf ea:Examination ;
  rdfs:subClassOf ea:SummativeAssessment ;
  rdfs:comment "A greater form of a 'unit test', given at the conclusion of a course." .

#################################################################
# RUBRIC CLASSIFICATION
#################################################################

ea:Rubric a owl:Class ;
  rdfs:label "Rubric" ;
  skos:altLabel "scoring guide" .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Rubric .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Rubric ;
  rdfs:range ea:RubricTypeCategory .

ea:RubricTypeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:HolisticRubricType a owl:Class .
ea:AnalyticRubricType a owl:Class .
ea:DevelopmentalRubricType a owl:Class .

ea:HolisticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
  rdfs:comment "Provides an overall rating for a piece of work considering all aspects." .

ea:AnalyticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: one passage lists holistic, analytic, and developmental rubrics as three coordinate (disjoint) classifications; another passage states developmental rubrics are 'a subset of analytical rubrics'. Both the coordinate partition (via RubricTypeCategory disjointUnion) and the subClassOf AnalyticRubric axiom are encoded." .

#################################################################
# GRADING APPROACH
#################################################################

ea:GradingApproach a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:HolisticGrading a owl:Class ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Scoring essays using a simple grading structure that bases a grade on overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:comment "Takes more factors into account, involving criterion-by-criterion judgments." .

#################################################################
# TEST SCORE INTERPRETATION
#################################################################

ea:TestScoreInterpretation a owl:Class ;
  owl:disjointUnionOf ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) ;
  rdfs:comment "There are two types of test score interpretations." .

ea:NormReferencedScoreInterpretation a owl:Class ;
  rdfs:comment "Compares test takers to a sample of peers to rank them." .

ea:CriterionReferencedScoreInterpretation a owl:Class ;
  rdfs:comment "Compares test takers to a criterion regardless of other examinees' scores." .

#################################################################
# COMPLEX ASSESSMENT
#################################################################

ea:Examiner a owl:Class .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .

ea:hasExaminer a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Examiner .

ea:ComplexAssessment a owl:Class ;
  rdfs:label "Complex Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
    [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal." .

#################################################################
# CONTINUOUS ASSESSMENT
#################################################################

ea:hasComponent a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:EducationalAssessment .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:FormativeAssessment ] ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course and will often include some form of formative assessment." .

#################################################################
# VALIDITY EVIDENCE
#################################################################

ea:ValidityEvidence a owl:Class ;
  rdfs:label "Validity Evidence" .

ea:hasValidityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ValidityEvidence .

ea:hasValidityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ValidityEvidence ;
  rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .

ea:ValidityEvidenceCoordinatePartition a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:ConsequentialValidity ea:FaceValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: one passage presents Content, Criterion, Construct, Consequential, and Face validity as five coordinate categories of validity evidence (hence asserted pairwise disjoint). Another passage states 'Construct validity ... subsumes all other types of validity' and that modern theory treats it as 'the overarching concern ... subsuming all other types of validity evidence such as content validity and criterion validity'. Both the disjointness and the subsumption (ContentValidity/CriterionValidity subClassOf ConstructValidity) are encoded, which renders those subclasses formally empty -- a deliberate, faithful record of the conflicting source claims." .

ea:hasValidityTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ;
  rdfs:range ea:ValidityTimingCategory .

ea:ValidityTimingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .

ea:ConcurrentTiming a owl:Class .
ea:PredictiveTiming a owl:Class .

ea:ConcurrentValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasValidityTiming ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] ;
  rdfs:comment "Test data and criterion data are collected at the same time." .

ea:PredictiveValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasValidityTiming ; owl:someValuesFrom ea:PredictiveTiming ] ) ] ;
  rdfs:comment "Test data are collected first to predict criterion data collected at a later time." .

ea:hasConstructRelationType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ConstructValidity ;
  rdfs:range ea:ConstructRelationCategory .

ea:ConstructRelationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ConvergentRelation ea:DiscriminantRelation ) .

ea:ConvergentRelation a owl:Class .
ea:DiscriminantRelation a owl:Class .

ea:ConvergentValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ConstructValidity
    [ a owl:Restriction ; owl:onProperty ea:hasConstructRelationType ; owl:someValuesFrom ea:ConvergentRelation ] ) ] ;
  rdfs:comment "Two measures of constructs that should theoretically be related are in fact related. One of the two subtypes of construct validity." .

ea:DiscriminantValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ConstructValidity
    [ a owl:Restriction ; owl:onProperty ea:hasConstructRelationType ; owl:someValuesFrom ea:DiscriminantRelation ] ) ] ;
  rdfs:comment "Concepts that are supposed to be unrelated are in fact unrelated. One of the two subtypes of construct validity." .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:label "Reliability" ;
  rdfs:comment "TENSION: the corpus offers two different, non-aligned enumerations both called classifications of 'reliability': (1) 'general classes of reliability estimates' (inter-rater, test-retest, inter-method, internal consistency), modeled as ea:ReliabilityEstimate; and (2) 'four types of reliability' based on error source (student-related, rater-related, test-administration-related, test-related), modeled as ea:ReliabilitySourceType. Both taxonomies are encoded as separate disjoint partitions under Reliability." .

ea:hasReliabilityEstimate a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ReliabilityEstimate .

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:ReliabilityEstimate ;
  rdfs:range xsd:decimal .

ea:ReliabilityEstimate a owl:Class ;
  rdfs:subClassOf ea:Reliability ;
  owl:disjointUnionOf ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:InterRaterReliability a owl:Class ;
  rdfs:comment "Degree of agreement between two or more raters in their appraisals." .

ea:TestRetestReliability a owl:Class ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next; includes intra-rater reliability." .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:InterMethodReliability a owl:Class ;
  skos:altLabel "parallel-forms reliability" ;
  rdfs:comment "Degree to which test scores are consistent when the method or instrument varies." .

ea:InternalConsistencyReliability a owl:Class ;
  rdfs:comment "Consistency of results across items within a test, commonly measured with Cronbach's alpha." .

ea:ReliabilitySourceType a owl:Class ;
  rdfs:subClassOf ea:Reliability ;
  owl:disjointUnionOf ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                         ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

ea:StudentRelatedReliability a owl:Class ; rdfs:comment "Can include personal problems, sickness, or fatigue." .
ea:RaterRelatedReliability a owl:Class ; rdfs:comment "Includes bias and subjectivity." .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:comment "Concerns the conditions of the test-taking process." .
ea:TestRelatedReliability a owl:Class ; rdfs:comment "Related to the nature of a test." .

ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:comment "Four practical strategies developed to estimate test reliability." ;
  owl:disjointUnionOf ( ea:TestRetestMethod ea:ParallelFormsMethod ea:SplitHalfMethod ea:InternalConsistencyMethod ) .

ea:TestRetestMethod a owl:Class .
ea:ParallelFormsMethod a owl:Class ; skos:altLabel "alternate-forms method" .
ea:SplitHalfMethod a owl:Class .
ea:InternalConsistencyMethod a owl:Class .

#################################################################
# LEARNING TYPES (Formal / Non-Formal / Informal)
#################################################################

ea:Learning a owl:Class ;
  owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

ea:FormalLearning a owl:Class ;
  rdfs:comment "Learning that occurs within the formal learning system." .

ea:NonFormalLearning a owl:Class ;
  rdfs:comment "Organized learning outside the formal learning system, e.g. clubs and workshops." .

ea:InformalLearning a owl:Class ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience, is self-directed, and typically does not lead to accreditation." .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:label "Transfer of Learning" .

ea:hasTransferContext a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferContextCategory .

ea:TransferContextCategory a owl:Class ;
  owl:disjointUnionOf ( ea:SimilarContext ea:DifferentContext ) .

ea:SimilarContext a owl:Class .
ea:DifferentContext a owl:Class .

ea:NearTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferContext ; owl:someValuesFrom ea:SimilarContext ] ) ] .

ea:FarTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferContext ; owl:someValuesFrom ea:DifferentContext ] ) ] .

ea:hasTransferEffect a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferEffectCategory .

ea:TransferEffectCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PositiveEffect ea:NegativeEffect ) .

ea:PositiveEffect a owl:Class .
ea:NegativeEffect a owl:Class .

ea:PositiveTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferEffect ; owl:someValuesFrom ea:PositiveEffect ] ) ] .

ea:NegativeTransfer a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
    [ a owl:Restriction ; owl:onProperty ea:hasTransferEffect ; owl:someValuesFrom ea:NegativeEffect ] ) ] .

#################################################################
# LEARNING OUTCOMES
#################################################################

ea:LearningOutcome a owl:Class .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:LearningOutcome .

ea:hasOutcomeCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:LearningOutcome ;
  rdfs:range ea:OutcomeCategoryClass .

ea:OutcomeCategoryClass a owl:Class ;
  owl:disjointUnionOf ( ea:IntendedCategory ea:MeasuredCategory ea:UnintendedCategory ) .

ea:IntendedCategory a owl:Class .
ea:MeasuredCategory a owl:Class .
ea:UnintendedCategory a owl:Class .

ea:IntendedLearningOutcome a owl:Class ;
  skos:altLabel "aim" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:LearningOutcome
    [ a owl:Restriction ; owl:onProperty ea:hasOutcomeCategory ; owl:someValuesFrom ea:IntendedCategory ] ) ] .

ea:MeasuredLearningOutcome a owl:Class ;
  skos:altLabel "objective" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:LearningOutcome
    [ a owl:Restriction ; owl:onProperty ea:hasOutcomeCategory ; owl:someValuesFrom ea:MeasuredCategory ] ) ] .

ea:UnintendedLearningOutcome a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:LearningOutcome
    [ a owl:Restriction ; owl:onProperty ea:hasOutcomeCategory ; owl:someValuesFrom ea:UnintendedCategory ] ) ] ;
  rdfs:comment "Beneficial outcomes neither planned nor sought but simply observed." .

ea:LearningOutcomeTaxonomy a owl:Class ;
  rdfs:comment "Types of learning outcome taxonomy include Bloom's taxonomy, SOLO, the DIKW pyramid, and the Model of Hierarchical Complexity." ;
  owl:disjointUnionOf ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

ea:BloomsTaxonomy a owl:Class .
ea:StructureOfObservedLearningOutcome a owl:Class ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class .
ea:ModelOfHierarchicalComplexity a owl:Class .

#################################################################
# COMPETENCY-BASED EDUCATION
#################################################################

ea:CompetencyBasedEducation a owl:Class ;
  rdfs:label "Competency-Based Education" ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based education", "performance-based education", "standards-based education" ;
  rdfs:comment "Systems of instruction, assessment, grading, and academic reporting based on students demonstrating learning. NOTE: the term 'standards-based' is also used elsewhere in the corpus as an altLabel for CriterionReferencedAssessment, producing overlapping terminology across distinct concepts." .

#################################################################
# TEACHER EVALUATION MEASURES
#################################################################

ea:TeacherEvaluationMeasure a owl:Class .

ea:ValueAddedMeasure a owl:Class ;
  rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Estimates a teacher's effect on student learning using statistical algorithms and standardized-test results." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  rdfs:comment "A related but distinct method of using test scores to quantify academic growth, which may also be used in teacher evaluation." .

#################################################################
# PORTFOLIOS
#################################################################

ea:StudentPortfolio a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  skos:altLabel "portfolio", "portfolio-based assessment" .

ea:DigitalPortfolio a owl:Class ;
  rdfs:subClassOf ea:StudentPortfolio ;
  skos:altLabel "e-portfolio" .

ea:CapstonePortfolio a owl:Class ;
  rdfs:subClassOf ea:StudentPortfolio ;
  rdfs:comment "Student work completed as part of long-term, culminating projects." .

#################################################################
# ASSESSMENT QUALITY ISSUES
#################################################################

ea:AssessmentQualityIssue a owl:Class ;
  owl:disjointUnionOf ( ea:MeasurementError ea:ScoreInflation ea:TestBias ) .

ea:MeasurementError a owl:Class ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge, or errors introduced in collecting/calculating data." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Student scores increase without genuine improvement in learning." .

ea:TestBias a owl:Class ;
  rdfs:comment "Cultural, class, ethnic or gender bias built into decisions about relevant subject matter and content." .

#################################################################
# MEASUREMENT THEORY
#################################################################

ea:MeasurementTheory a owl:Class ;
  rdfs:comment "Approaches originally developed for the analysis of data from educational assessments." ;
  owl:disjointUnionOf ( ea:ClassicalTestTheory ea:ItemResponseTheory ea:RaschModel ) .

ea:ClassicalTestTheory a owl:Class .
ea:ItemResponseTheory a owl:Class .
ea:RaschModel a owl:Class .

#################################################################
# CORRECTIVE FEEDBACK
#################################################################

ea:CorrectiveFeedback a owl:Class ;
  rdfs:comment "Formal or informal feedback on understanding or performance; to succeed it must be nonevaluative, supportive, timely, and specific." .

ea:Recast a owl:Class ;
  rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors by a parent or caregiver." .

#################################################################
# DATATYPE PROPERTIES (general)
#################################################################

ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Examination ;
  rdfs:range xsd:integer .

```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment """Ontology of educational assessment built from a corpus that repeatedly classifies
the same terms along independent, cross-cutting axes (purpose, response type, referencing,
formality, administering source, standardization, stakes) and that, in several places,
contradicts itself about whether a kind is a coordinate sibling of another kind or a
subclass of it. Per modelling instructions, BOTH sides of every such conflict are asserted,
with an rdfs:comment flagging the tension at the relevant axiom.""" .

#################################################################
# 1. TOP CLASS
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "Educational Evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests. Can focus on the individual learner, the learning community, a course, a program, the institution, or the educational system (granularity)." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "Examination", "Exam", "Evaluation" ;
  rdfs:comment "An examination (exam or evaluation), or test, is an educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in some topic." .

#################################################################
# 2. GRANULARITY / SCOPE AXIS
#################################################################

ea:hasAssessmentScope a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class .
ea:IndividualLearnerLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemLevel a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:IndividualLearnerLevel ea:LearningCommunityLevel ea:CourseLevel
    ea:ProgramLevel ea:InstitutionLevel ea:EducationalSystemLevel ) .

#################################################################
# 3. PURPOSE AXIS (placement, formative, summative, diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory ; skos:altLabel "initial purpose" .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Corpus passage 1/2 lists placement, formative, summative, diagnostic as four coordinate categories. A later passage instead says assessment 'is often divided into initial, formative, and summative categories' (a three-way split in which initial = placement), omitting diagnostic as a coordinate peer -- consistent with diagnostic being elsewhere treated as a subtype of formative. Both the four-way coordinate partition and the subordinating claims are encoded; see ea:DiagnosticAssessment." .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "Pre-assessment", "Initial Assessment", "Threshold Knowledge Test", "TKT" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students according to prior achievement/characteristics at the most appropriate point in instruction; conducted before instruction; generally not graded." .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "Educative Assessment", "Assessment For Learning", "Classroom Assessment", "Formative Evaluation", "Formative Feedback" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Carried out throughout a course to provide feedback and guide instruction; not necessarily graded." .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "Assessment Of Learning", "Summative Evaluation" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Carried out at the end of a course or project; typically graded and used to assign a course grade." .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic Assessment" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: ea:PurposeCategory asserts Placement/Formative/Summative/Diagnostic as pairwise-disjoint coordinate kinds, yet the corpus also states 'A common form of formative assessment is diagnostic assessment' and describes 'formative assessment ... including diagnostic testing', making DiagnosticAssessment a subclass of FormativeAssessment. Both claims are encoded." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# 4. RESPONSE-TYPE AXIS (objective vs subjective) — assessment level
#################################################################

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ResponseTypeCategory .

ea:ResponseTypeCategory a owl:Class .
ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:ResponseTypeCategory owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer. Some argue the objective/subjective distinction is neither useful nor accurate, since all assessment embeds bias." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it." .

#################################################################
# 5. REFERENCING AXIS (criterion / norm / ipsative)
#################################################################

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferenceTypeCategory .

ea:ReferenceTypeCategory a owl:Class .
ea:CriterionReference a owl:Class ; rdfs:subClassOf ea:ReferenceTypeCategory .
ea:NormReference a owl:Class ; rdfs:subClassOf ea:ReferenceTypeCategory .
ea:IpsativeReference a owl:Class ; rdfs:subClassOf ea:ReferenceTypeCategory .
ea:ReferenceTypeCategory owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "Criterion-Referenced Test", "CRT", "Standards-Based Assessment" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria (e.g., driving test). Best-known example: the driving test. NOTE: the term 'standards-based assessment' is also used elsewhere for a performance-based-assessment variant (see ea:PerformanceBasedAssessment) -- a terminological tension." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "Norm-Referenced Test", "NRT", "Normative Assessment", "Grading On A Curve" ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] ;
  rdfs:comment "Measured relative to the student body taking it, not against defined criteria. Best-known example: the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
  rdfs:comment "Self-comparison, either in the same domain over time or across domains within the same student." .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:CriterionReferencedAssessment ;
  rdfs:range xsd:decimal ;
  skos:altLabel "cutoff score", "passing score" .

ea:MasteryTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:CriterionReferencedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test that involves a cutscore; not all criterion-referenced tests have one." .

ea:hasPercentileRank a owl:DatatypeProperty ;
  rdfs:domain ea:NormReferencedAssessment ;
  rdfs:range xsd:decimal .

#################################################################
# 6. FORMALITY AXIS
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document (test, quiz, paper); given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Does not contribute to a student's final grade; may include observation, checklists, rubrics, participation." .

#################################################################
# 7. ADMINISTERING-SOURCE AXIS (internal / external)
#################################################################

ea:hasAdministeringSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministeringSourceCategory .

ea:AdministeringSourceCategory a owl:Class .
ea:InternalSource a owl:Class ; rdfs:subClassOf ea:AdministeringSourceCategory .
ea:ExternalSource a owl:Class ; rdfs:subClassOf ea:AdministeringSourceCategory .
ea:AdministeringSourceCategory owl:disjointUnionOf ( ea:InternalSource ea:ExternalSource ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringSource ; owl:someValuesFrom ea:InternalSource ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministeringSource ; owl:someValuesFrom ea:ExternalSource ] ) ] ;
  rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
# 8. STANDARDIZATION AXIS
#################################################################

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent/standard manner for all test takers. Most standardized tests are summative assessments (cross-axis correlation claim, not a subclass claim)." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Significantly different tests given to different test takers, or the same test under significantly different conditions/evaluation." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Backward-looking: measures knowledge/skills already learned." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Forward-looking: attempts to predict ability to succeed in a future endeavor." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

#################################################################
# 9. STAKES AXIS
#################################################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward or important consequence for performance." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] ;
  rdfs:comment "Most standardized tests, such as ordinary classroom quizzes, are low-stakes." .

#################################################################
# 10. CROSS-CUTTING NAMED TEST KINDS (multiple classification)
#################################################################

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:Test, ea:NormReferencedAssessment, ea:HighStakesTest ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected (e.g., civil service exams). Illustrates corpus claim: 'Most tests can be classified on multiple categories'." .

#################################################################
# 11. PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; similar to summative assessment in focusing on achievement, often aligned with standards-based assessment." .

ea:hasPerformanceFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceFormatCategory a owl:Class .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceEventFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceEventFormat ) ;
  rdfs:comment "Performance formats are further classified into products (painting, portfolio, paper, exhibition) and performances (speech, athletic skill, musical recital, reading)." .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside of school. TENSION: one passage lists Authentic Assessment as a coordinate sibling of Performance-Based Assessment in an enumerated 'Assessment types' list, while the Glossary states 'Performance assessments may also be called authentic assessments', implying equivalence. Both the coordinate-listing and the synonymy claim are preserved (no subClassOf/equivalentClass link asserted between them, per the coordinate-list reading; the synonymy is only noted here)." .

ea:PortfolioAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  skos:altLabel "Student Portfolio", "E-Portfolio", "Digital Portfolio", "Portfolio-Based Assessment" ;
  rdfs:comment "A compilation of academic work assembled to evaluate learning progress and achievement; listed as an example product of performance-based assessment." .

#################################################################
# 12. OTHER NAMED ASSESSMENT TYPES (Glossary enumerations)
#################################################################

ea:PreAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Glossary: administered before a lesson/unit to establish a baseline. TENSION: an earlier passage explicitly equates 'pre-assessment' with Placement Assessment (see ea:PlacementAssessment skos:altLabel), while the Glossary enumerates Pre-assessment and Placement assessment as two distinct, coordinate assessment types. Both claims are kept: PlacementAssessment carries the altLabel 'Pre-assessment', and ea:PreAssessment also exists as a separate class." .

ea:ScreeningAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to determine whether students need specialized assistance/services or are ready to begin a course or program." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "Benchmark Assessment" ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Used periodically to determine whether students are on track for later summative tests. Corpus: 'Some educators consider interim tests to be formative ... but others may consider them to be summative' -- modelled as subclass of the union of the two, reflecting the unresolved debate." .

ea:CommonAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Used across a school/district to ensure consistent evaluation; 'Common assessments may be formative or summative.'" .

ea:ComplexAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ] ) ] ;
  rdfs:comment "Requires a rubric and an expert examiner; example items include thesis and funding proposal; complexity arises from format implicitness (e.g., final-year-project theses)." .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; alternative to a single final-examination system; often includes some form of formative assessment." .

ea:hasComponent a owl:ObjectProperty ;
  rdfs:domain ea:ContinuousAssessment ;
  rdfs:range ea:FormativeAssessment .

#################################################################
# 13. MIDTERM / FINAL / QUIZ / UNIT TEST
#################################################################

ea:UnitTest a owl:Class ; rdfs:subClassOf ea:Test .

ea:MidtermExamination a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "An exam given near the middle of a term; 'Midterm exams are a type of formative or summative assessment.'" .

ea:FinalExamination a owl:Class ;
  rdfs:subClassOf ea:UnitTest, ea:SummativeAssessment ;
  rdfs:comment "'A final is technically just a greater form of a unit test.' Makes a final review of topics covered." .

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low weight; instructors usually provide it as a formative assessment." .

#################################################################
# 14. TEST ITEM TAXONOMY
#################################################################

ea:ItemBank a owl:Class ; rdfs:comment "Items are stored in an item bank." .

ea:TestItem a owl:Class ;
  rdfs:comment "The general term for a question/prompt in a test; 'item' is preferred over 'question' because not all items are phrased as questions." .

ea:isItemOf a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

ea:hasItem a owl:ObjectProperty ;
  owl:inverseOf ea:isItemOf ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ObjectiveItem owl:disjointWith ea:SubjectiveItem .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ; skos:altLabel "MCQ", "Objective Response Item" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:ObjectiveItem owl:disjointUnionOf
  ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) ;
  rdfs:comment "Per 'Objective question types include true/false, multiple-choice, multiple-response, and matching questions' these four are coordinate, pairwise-disjoint kinds of objective item. TENSION: elsewhere the corpus states 'There are two families of multiple-choice questions. The first family is known as the True/False question ... The second ... One-Best-Answer', which instead makes TrueFalseItem a SUBCLASS of MultipleChoiceItem. Both the coordinate/disjoint axiom and the subsumption axiom below are encoded." .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem .
ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires the test taker to answer only one from a list of answers (second family of multiple-choice item)." .

ea:ExtendedResponseItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "Essay Item", "Essay Question", "Free Response Question", "FRQ" ;
  rdfs:comment "An open-ended question requiring a prose response; graded for factual correctness as well as persuasiveness, style, and mastery." .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:hasStemText a owl:DatatypeProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range xsd:string .

ea:AnswerOption a owl:Class .

ea:hasAnswerOption a owl:ObjectProperty ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:AnswerOption .

ea:hasKey a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasAnswerOption ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "The correct answer option(s)." .

ea:hasDistractor a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasAnswerOption ;
  rdfs:domain ea:MultipleChoiceItem ;
  rdfs:range ea:AnswerOption ;
  rdfs:comment "Incorrect answer option(s), designed to be plausible yet clearly wrong." .

ea:MultipleChoiceItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:cardinality "1"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minCardinality "2"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "More than one answer may be keyed as correct, in contrast to MultipleChoiceItem." .

#################################################################
# 15. SCORING METHODS / RUBRICS
#################################################################

ea:ScoringMethod a owl:Class .
ea:HolisticScoring a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  skos:altLabel "Holistic Grading", "Nonreductionist Grading" .
ea:AnalyticScoring a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  skos:altLabel "Analytic Grading" .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  rdfs:comment "Trains raters against a scoring guide with criteria scaled to accomplishment levels; close to analytic scoring but remains holistic at heart -- an explicit hybrid, not cleanly disjoint from either Holistic or Analytic scoring." .
ea:FormulaScoring a owl:Class ; rdfs:subClassOf ea:ScoringMethod ;
  rdfs:comment "Score is reduced in proportion to incorrect responses to negate benefits of random guessing." .

ea:HolisticScoring owl:disjointWith ea:AnalyticScoring ;
  rdfs:comment "Holistic grading contrasts with analytic grading, which takes more factors into account when assigning a grade." .

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham); typically a table with criteria, quality definitions, and a scoring strategy." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Rubric .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "'Rubrics can be classified as holistic, analytic, or developmental' presents the three as coordinate, pairwise-disjoint kinds." .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: the corpus also states 'Developmental rubrics, a subset of analytical rubrics' which contradicts the disjointUnion coordinate-partition axiom above (DevelopmentalRubric disjoint from AnalyticRubric). Both are encoded." .

#################################################################
# 16. VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:hasValidityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:Validity .

ea:hasValidityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Validity ;
  rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "Logical Validity", "Subject-Matter Validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "Criterion-Related Validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

:AllDisjointValidity a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) ;
  rdfs:comment "'Validity of an assessment is generally gauged through examination of evidence in the following categories: Content validity, Criterion validity, Construct validity. Others are: consequential validity, face validity' -- presented as coordinate (pairwise-disjoint) evidence categories." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: 'Construct validity ... subsumes all other types of validity' and 'Modern validity theory defines construct validity as the overarching concern of validity research, subsuming all other types of validity evidence such as content validity and criterion validity' directly contradicts the coordinate, pairwise-disjoint treatment of Content/Criterion/Construct/Face/Consequential validity asserted above. Both the disjointness and the subsumption are encoded." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) ;
  rdfs:comment "Concurrent validity: test data and criterion data collected at the same time. Predictive validity: test data collected first, criterion data collected later." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
  rdfs:comment "'Convergent and discriminant validity are the two subtypes of validity that make up construct validity.'" .

#################################################################
# 17. RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment. NOTE: the corpus gives two parallel, non-aligned classifications under the single term 'reliability': (a) 'four types of reliability' classified by SOURCE of error (student-related, rater-related, test-administration-related, test-related), and (b) 'several general classes of reliability estimates' classified by ESTIMATION METHOD (inter-rater, test-retest, inter-method, internal-consistency). Both are modelled as subclasses of Reliability." .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .

ea:Reliability owl:disjointUnionOf
  ( ea:StudentRelatedReliability ea:RaterRelatedReliability
    ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters." .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "Repeatability" ;
  rdfs:comment "Consistency of scores from one test administration to the next; includes intra-rater reliability." .
ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "Parallel-Forms Reliability" ;
  rdfs:comment "Consistency of scores when there is variation in methods/instruments used." .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Consistency of results across items within a test; commonly estimated with Cronbach's alpha." .

:AllDisjointReliabilityEstimates a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

#################################################################
# 18. TEACHER-EVALUATION METHODS
#################################################################

ea:TeacherEvaluationMethod a owl:Class .
ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ;
  skos:altLabel "Growth Measure" .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ;
  rdfs:comment "A related but distinct method from value-added measures for quantifying academic achievement and growth." .
ea:ValueAddedMeasure owl:disjointWith ea:StudentGrowthMeasure .

#################################################################
# 19. COMPETENCY-BASED LEARNING
#################################################################

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "Proficiency-Based Learning", "Mastery-Based Learning", "Outcome-Based Learning",
                "Performance-Based Learning", "Standards-Based Learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learning. NOTE: the altLabel 'Performance-Based Learning' here names an educational-system concept distinct from ea:PerformanceBasedAssessment (a kind of assessment task); the corpus reuses the term 'performance-based' for both, a terminological tension flagged here." .

#################################################################
# 20. MEASUREMENT ERROR / SCORE INFLATION
#################################################################

ea:MeasurementError a owl:Class ;
  rdfs:comment "Generally refers to either (1) the difference between a test score and a student's actual knowledge/ability or (2) errors introduced when collecting/calculating education data." .
ea:ScoreMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:DataReportingError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:MeasurementError owl:disjointUnionOf ( ea:ScoreMeasurementError ea:DataReportingError ) .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Student scores increase without genuine learning improvement, due to flawed testing design or inadvertent/intentional inflation by educators." .

#################################################################
# 21. FEEDBACK
#################################################################

ea:Feedback a owl:Class .
ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Must be nonevaluative, supportive, timely, and specific." .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A parent/caregiver's subtle correction of a young child's spoken error (motherese)." .

#################################################################
# 22. LEARNING OUTCOMES
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:LearningOutcome .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "Aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "Objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .

ea:LearningOutcome owl:disjointUnionOf
  ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class .
ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

ea:LearningOutcomeTaxonomy owl:disjointUnionOf
  ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# 23. TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "The application of skill, knowledge or understanding to resolve a novel problem or situation." .

ea:hasTransferDistance a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferDistanceCategory .
ea:TransferDistanceCategory a owl:Class .
ea:NearDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:FarDistance a owl:Class ; rdfs:subClassOf ea:TransferDistanceCategory .
ea:TransferDistanceCategory owl:disjointUnionOf ( ea:NearDistance ea:FarDistance ) .

ea:NearTransfer a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:NearDistance ] ) ] .
ea:FarTransfer a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferDistance ; owl:someValuesFrom ea:FarDistance ] ) ] .

ea:hasTransferValence a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TransferOfLearning ;
  rdfs:range ea:TransferValenceCategory .
ea:TransferValenceCategory a owl:Class .
ea:PositiveValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:NegativeValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:TransferValenceCategory owl:disjointUnionOf ( ea:PositiveValence ea:NegativeValence ) .

ea:PositiveTransfer a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:PositiveValence ] ) ] .
ea:NegativeTransfer a owl:Class ;
  owl:equivalentClass [ a owl:Class ;
    owl:intersectionOf ( ea:TransferOfLearning
      [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:NegativeValence ] ) ] .

#################################################################
# 24. LEARNING TYPES (formal / non-formal / informal)
#################################################################

ea:Learning a owl:Class .
ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Implied contrast class: leads to accreditation, unlike informal learning." .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system (e.g., clubs, workshops)." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; experiential, day-to-day, typically does not lead to accreditation." .

ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# 25. DATATYPE PROPERTIES OF GENERAL USE
#################################################################

ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

ea:hasScoringMethod a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ScoringMethod .
