```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment#> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" ;
  rdfs:comment "Models assessment, test, validity, reliability and related classification axes as stated in the source corpus, including contradictory classification claims noted explicitly." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification; administered verbally, on paper, on computer, or in a predetermined area. Modeled as a subclass of Assessment because 'assessment is often used interchangeably with test but is not limited to tests'." .

ea:Examination owl:equivalentClass ea:Test ;
  a owl:Class ;
  rdfs:label "Examination" ;
  skos:altLabel "exam" , "evaluation" ;
  rdfs:comment "'An examination (exam or evaluation), or test, is an educational assessment...' and 'An examination (exam) is a test.' Note tension: 'evaluation' is also used as a synonym for the broader class Assessment elsewhere in the corpus." .

#################################################################
# GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole (granularity)." .

ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:SystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:SystemGranularity ) .

#################################################################
# AXIS: PURPOSE  (Placement / Formative / Summative / Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory ;
  rdfs:comment "Reified classification axis: 'Assessment is often divided into initial, formative, and summative categories' / 'Placement, formative, summative and diagnostic assessment'. Not declared functional because the corpus elsewhere states diagnostic assessment is a form of formative assessment, which would be unsatisfiable under a functional reading." .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment" , "initial assessment" , "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students according to prior achievement or level of knowledge at the most appropriate point in an instructional sequence; conducted before instruction to establish a baseline." .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "educative assessment" , "assessment for learning" , "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Conducted throughout a course to provide ongoing feedback and modify teaching and learning activities; typically not graded." .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Carried out at the end of a course or project to assign a grade and summarize what students have learned." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists 'Placement, formative, summative and diagnostic assessment' as four coordinate, mutually exclusive categories (encoded via the disjoint PurposeCategory partition), while another states 'A common form of formative assessment is diagnostic assessment' and that formative assessment includes 'diagnostic testing' (encoded here as DiagnosticAssessment rdfs:subClassOf FormativeAssessment). Both claims are asserted per corpus instructions." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  skos:altLabel "performance assessment" ;
  rdfs:comment "Performance-based assessment is similar to summative assessment in that it focuses on achievement, and is most commonly associated with standards-based assessment." .

ea:PerformanceBasedAssessment skos:closeMatch ea:SummativeAssessment , ea:AuthenticAssessment , ea:StandardsBasedAssessment .

ea:hasPerformanceFormat a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceFormatCategory a owl:Class .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceFormat ) .

#################################################################
# AXIS: OBJECTIVITY (Objective / Subjective)
#################################################################

ea:hasObjectivity a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveType a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveType a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveType ea:SubjectiveType ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveType ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveType ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or more than one way of expressing the correct answer." .

#################################################################
# TEST ITEM TAXONOMY
#################################################################

ea:TestItem a owl:Class ;
  rdfs:comment "Stored in an item bank; consists of a stem and alternative answers for closed formats." .

ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ; rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ; skos:altLabel "MCQ" , "multiple choice question" , "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem where only one answer may be keyed as correct." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:ObjectiveItem owl:disjointUnionOf
  ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:SubjectiveItem owl:disjointUnionOf ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:FreeResponseItem owl:equivalentClass ea:EssayItem ;
  a owl:Class ;
  skos:altLabel "FRQ" ;
  rdfs:comment "'A free response question (FRQ) or essay question is a type of open-ended question...'" .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: elsewhere True/False is listed as a coordinate, disjoint objective item type alongside MultipleChoiceItem ('Objective question types include true/false, multiple-choice...'). However another passage states 'There are two families of multiple-choice questions. The first family is known as the True/False question...', subordinating True/False under MultipleChoiceItem. Both axioms asserted per corpus." .

ea:OneBestAnswerItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "The second family of multiple-choice questions; requires a test taker to answer only one from a list of answers." .

ea:hasStem a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:TestItem ; rdfs:range xsd:string .

ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:AnswerOption owl:disjointUnionOf ( ea:Key ea:Distractor ) .

ea:hasAnswerOption a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key .
ea:hasDistractor a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Distractor .

ea:MultipleChoiceItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
    owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ;
    owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires recall of a term; may or may not provide a word bank." .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  rdfs:comment "Items such as short answer or essay typically require a test taker to write a response." .

ea:MathematicsItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Most mathematics questions employ a style which does not fall into any of the objective/subjective categories above; marks are given for steps as well as the final answer." .

ea:hasResponseMode a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:ResponseModeCategory .

ea:ResponseModeCategory a owl:Class .
ea:WrittenResponseMode a owl:Class ; rdfs:subClassOf ea:ResponseModeCategory .
ea:PerformanceResponseMode a owl:Class ; rdfs:subClassOf ea:ResponseModeCategory .
ea:ResponseModeCategory owl:disjointUnionOf ( ea:WrittenResponseMode ea:PerformanceResponseMode ) .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasResponseMode ; owl:someValuesFrom ea:WrittenResponseMode ] ) ] ;
  rdfs:comment "Administered on paper or on a computer; respondent writes or types within a given space." .

ea:PerformanceTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasResponseMode ; owl:someValuesFrom ea:PerformanceResponseMode ] ) ] ;
  rdfs:comment "Requires an examinee to actually perform a task or activity, rather than simply answering questions, to ensure greater fidelity to what is being tested." .

#################################################################
# RUBRIC TYPES
#################################################################

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham)." .

ea:hasRubricType a owl:ObjectProperty ; rdfs:domain ea:Rubric ; rdfs:range ea:RubricTypeCategory .

ea:RubricTypeCategory a owl:Class .
ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:RubricTypeCategory owl:disjointUnionOf
  ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:HolisticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] .

ea:AnalyticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] .

ea:DevelopmentalRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents three coordinate, disjoint kinds (encoded in RubricTypeCategory). But 'Developmental rubrics, a subset of analytical rubrics' subordinates Developmental under Analytic (encoded via direct subClassOf). Both asserted." .

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ; skos:altLabel "holistic scoring" , "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach .
ea:GradingApproach owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trait-informed scoring 'comes close to analytic scoring methods' yet 'remains holistic at heart' -- the corpus treats it as holistic overall while noting its proximity to analytic methods; both aspects are noted here." .

ea:hasGradingApproach a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:GradingApproach .

#################################################################
# AXIS: REFERENCING (Criterion / Norm / Ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Candidates are measured against defined (and objective) criteria, e.g. the driving test." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  skos:altLabel "normative assessment" , "grading on the curve" ;
  rdfs:comment "Measured relative to the student body taking it; the IQ test is the best-known example." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  skos:altLabel "forced-choice assessment" ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:StandardsBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "'Criterion-referenced tests have also been called standards-based assessments...as students are assessed with regard to standards.'" .
ea:StandardsBasedAssessment skos:closeMatch ea:CriterionReferencedAssessment .

ea:TestScoreInterpretation a owl:Class ;
  rdfs:comment "There are two types of test score interpretations: norm-referenced and criterion-referenced." .

ea:NormReferencedScoreInterpretation a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestScoreInterpretation
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:CriterionReferencedScoreInterpretation a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestScoreInterpretation
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:TestScoreInterpretation owl:disjointUnionOf
  ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

#################################################################
# AXIS: FORMALITY (Formal / Informal)
#################################################################

ea:hasFormality a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalType a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalType ea:InformalType ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalType ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalType ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade." .

#################################################################
# AXIS: LOCUS (Internal / External)
#################################################################

ea:hasLocus a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# AXIS: STAKES (High / Low)
#################################################################

ea:hasStakes a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesValue a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesValue a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesValue ea:LowStakesValue ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesValue ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance / important consequences for the test taker." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesValue ] ) ] .

#################################################################
# AXIS: STANDARDIZATION (Standardized / Non-standardized)
#################################################################

ea:hasStandardization a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedValue a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedValue a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedValue ea:NonStandardizedValue ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedValue ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedValue ] ) ] ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

ea:hasTemporalOrientation a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:StandardizedTest ; rdfs:range ea:TemporalOrientationCategory .

ea:TemporalOrientationCategory a owl:Class .
ea:BackwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientationCategory .
ea:ForwardLookingOrientation a owl:Class ; rdfs:subClassOf ea:TemporalOrientationCategory .
ea:TemporalOrientationCategory owl:disjointUnionOf
  ( ea:BackwardLookingOrientation ea:ForwardLookingOrientation ) .

ea:AchievementTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:BackwardLookingOrientation ] ) ] ;
  rdfs:comment "Measures knowledge and skills already learned; 'backward-looking'." .

ea:AptitudeTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
      [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:ForwardLookingOrientation ] ) ] ;
  rdfs:comment "Attempts to predict ability to succeed in a future endeavor; 'forward-looking'." .

ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest ) .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:NormReferencedTest , ea:HighStakesTest ;
  rdfs:comment "Competitive exams are norm-referenced, high-stakes tests in which candidates are ranked and top rankers are selected." .

#################################################################
# NAMED TEST FORMS
#################################################################

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test , ea:FormativeAssessment , ea:LowStakesTest ;
  rdfs:comment "A brief assessment usually provided as a formative assessment and usually of little weight." .

ea:MidtermExam a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Midterm exams are a type of formative or summative assessment." .

ea:FinalExamination a owl:Class ;
  rdfs:subClassOf ea:Test , ea:SummativeAssessment ;
  rdfs:comment "A final review and assessment of each student's knowledge, technically a greater form of a unit test." .

#################################################################
# AUTHENTIC / PERFORMANCE / PORTFOLIO / CONTINUOUS ASSESSMENT
#################################################################

ea:hasAssessmentContext a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AssessmentContextCategory .

ea:AssessmentContextCategory a owl:Class .
ea:RealisticContext a owl:Class ; rdfs:subClassOf ea:AssessmentContextCategory .
ea:ArtificialContext a owl:Class ; rdfs:subClassOf ea:AssessmentContextCategory .
ea:AssessmentContextCategory owl:disjointUnionOf ( ea:RealisticContext ea:ArtificialContext ) .

ea:AuthenticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessmentContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
  rdfs:comment "The measurement of accomplishments within a realistic, practical context that is relevant outside of the school setting." .

ea:AssessmentInstrument a owl:Class .
ea:Rubric rdfs:subClassOf ea:AssessmentInstrument .
ea:StudentPortfolio a owl:Class ; rdfs:subClassOf ea:AssessmentInstrument ;
  rdfs:comment "A compilation of academic work and other forms of educational evidence." .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio ; skos:altLabel "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:StudentPortfolio .

ea:hasInstrument a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:AssessmentInstrument .

ea:PortfolioAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasInstrument ; owl:someValuesFrom ea:StudentPortfolio ] ;
  skos:altLabel "portfolio-based assessment" .

ea:hasComponent a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Assessment .

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:FormativeAssessment ] ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course, often used as an alternative to the final examination system; will often include some form of formative assessment." .

ea:CommonAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Used in a school or district to ensure consistent evaluation; may be formative or summative." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used periodically to evaluate progress toward future summative assessments. DISPUTED: 'Some educators consider interim tests to be formative...but others may consider them to be summative.' No subClassOf to either is asserted, reflecting the unresolved dispute noted by the corpus." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

ea:PreAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "TENSION: elsewhere Placement assessment is described as 'also referred to as pre-assessment' (synonym), but the Great Schools Partnership glossary lists Pre-assessment and Placement assessment as separate, coordinate items in its enumeration of assessment types. Both treatments are preserved: a skos:closeMatch link plus a distinct class." .
ea:PreAssessment skos:closeMatch ea:PlacementAssessment .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which a tool measures what it claims to measure; 'the degree to which evidence and theory support the interpretations of test scores'." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:Validity owl:disjointUnionOf
  ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
    ea:ConsequentialValidity ea:FaceValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConsequentialValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: one passage enumerates Content, Criterion, Construct, Consequential and Face validity as coordinate categories of validity evidence (encoded as a disjoint union of Validity). Another passage states construct validity 'subsumes all other types of validity' and that 'construct validity is not distinct from the support for the substantive theory' (encoded here as the other four being subClassOf ConstructValidity). Both are asserted per corpus." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

ea:hasTimingRelation a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .

ea:TimingCategory a owl:Class .
ea:ConcurrentTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:PredictiveTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:TimingCategory owl:disjointUnionOf ( ea:ConcurrentTiming ea:PredictiveTiming ) .

ea:ConcurrentValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasTimingRelation ; owl:someValuesFrom ea:ConcurrentTiming ] ) ] ;
  rdfs:comment "Test data and criterion data collected at the same time." .

ea:PredictiveValidity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasTimingRelation ; owl:someValuesFrom ea:PredictiveTiming ] ) ] ;
  rdfs:comment "Test data collected first to predict criterion data collected at a later point." .

ea:SubjectMatterValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Widely used in education; predicts the score a student would get on a similar test with different questions." .
ea:SubjectMatterValidity skos:closeMatch ea:ContentValidity .

ea:hasValidityCoefficient a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Validity ; rdfs:range xsd:decimal .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The freedom of a measure from measurement error; consistency of an assessment." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .

ea:Reliability owl:disjointUnionOf
  ( ea:InterRaterReliability ea:TestRetestReliability
    ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability ;
  rdfs:comment "Measurements gathered from a single rater using the same methods; this includes intra-rater reliability." .

ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "When dealing with forms, inter-method reliability may be termed parallel-forms reliability." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms, stepped up via the Spearman-Brown formula; related to Cronbach's alpha." .

ea:hasReliabilitySource a owl:ObjectProperty ;
  rdfs:domain ea:Reliability ; rdfs:range ea:ReliabilitySourceFactor .

ea:ReliabilitySourceFactor a owl:Class .
ea:StudentRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceFactor .
ea:RaterRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceFactor .
ea:TestAdministrationRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceFactor .
ea:TestRelatedFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceFactor .
ea:ReliabilitySourceFactor owl:disjointUnionOf
  ( ea:StudentRelatedFactor ea:RaterRelatedFactor
    ea:TestAdministrationRelatedFactor ea:TestRelatedFactor ) ;
  rdfs:comment "'There are four types of reliability: student-related...rater-related...test administration-related...and test-related.'" .

ea:hasReliabilityCoefficient a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0 (completely unreliable) to 1 (completely reliable)." .

ea:TestScore a owl:Class ; rdfs:comment "X = T + E: observed test score equals true score plus measurement error." .
ea:TrueScore a owl:Class ; rdfs:subClassOf ea:TestScore .
ea:ErrorScore a owl:Class ; rdfs:subClassOf ea:TestScore .
ea:ObservedScore a owl:Class ; rdfs:subClassOf ea:TestScore .

ea:MeasurementError a owl:Class ;
  rdfs:comment "Errors of measurement are composed of both random error and systematic error." .
ea:RandomError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:SystematicError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:MeasurementError owl:disjointUnionOf ( ea:RandomError ea:SystematicError ) .

#################################################################
# LEARNING OUTCOMES / CONSTRUCTIVE ALIGNMENT
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf
  ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "A principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# FEEDBACK
#################################################################

ea:CorrectiveFeedback a owl:Class ;
  rdfs:comment "Feedback that is nonevaluative, supportive, timely, and specific." .

ea:WrittenFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .
ea:OralFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback .
[] a owl:AllDisjointClasses ; owl:members ( ea:WrittenFeedback ea:OralFeedback ) .

ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors by a parent or caregiver." .

ea:hasFeedback a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:CorrectiveFeedback .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "The application of skill, knowledge or understanding to resolve a novel problem or situation." .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

#################################################################
# EVALUATION STANDARDS
#################################################################

ea:EvaluationStandard a owl:Class ;
  rdfs:comment "Published by the Joint Committee on Standards for Educational Evaluation." .

ea:PersonnelEvaluationStandard a owl:Class ; rdfs:subClassOf ea:EvaluationStandard .
ea:ProgramEvaluationStandard a owl:Class ; rdfs:subClassOf ea:EvaluationStandard .
ea:StudentEvaluationStandard a owl:Class ; rdfs:subClassOf ea:EvaluationStandard .
ea:EvaluationStandard owl:disjointUnionOf
  ( ea:PersonnelEvaluationStandard ea:ProgramEvaluationStandard ea:StudentEvaluationStandard ) .

ea:StandardCategory a owl:Class ;
  rdfs:comment "Each standard is placed in one of four fundamental categories: appropriate, useful, feasible, and accurate." .
ea:AppropriatenessStandard a owl:Class ; rdfs:subClassOf ea:StandardCategory .
ea:UtilityStandard a owl:Class ; rdfs:subClassOf ea:StandardCategory .
ea:FeasibilityStandard a owl:Class ; rdfs:subClassOf ea:StandardCategory .
ea:AccuracyStandard a owl:Class ; rdfs:subClassOf ea:StandardCategory .
ea:StandardCategory owl:disjointUnionOf
  ( ea:AppropriatenessStandard ea:UtilityStandard ea:FeasibilityStandard ea:AccuracyStandard ) .

#################################################################
# RELATED PHENOMENA (lightly modeled)
#################################################################

ea:TeachingToTheTest a owl:Class ;
  rdfs:comment "The process of deliberately narrowing instruction to focus only on material that will be measured on the test." .

ea:TestAnxiety a owl:Class ;
  rdfs:comment "Anxiety experienced when a person believes they are being judged and unlikely to receive a favorable evaluation." .

ea:Cheating a owl:Class ;
  rdfs:comment "The process of using unauthorized means or methods to obtain a desired test score or grade." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Results when student scores increase but the increase does not reflect genuine improvements in learning." .

ea:Proficiency a owl:Class ;
  rdfs:comment "A determination based on standards or measurement systems that a student or teacher has met expected performance levels." .

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning" , "mastery-based learning" , "outcome-based learning" ,
               "performance-based learning" , "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge and skills." .

ea:ValueAddedMeasure a owl:Class ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Estimates or quantifies how much effect individual teachers have on student learning during a school year, using statistical algorithms and standardized-test results." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:comment "A related but distinct method of using student test scores to quantify academic achievement and growth." .
ea:StudentGrowthMeasure skos:closeMatch ea:ValueAddedMeasure .

#################################################################
# DATATYPE PROPERTIES ON TEST
#################################################################

ea:hasItemCount a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:hasCutScore a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range xsd:decimal ;
  rdfs:comment "The score examinees must exceed to pass a mastery test (cutscore)." .
